import{_ as n,o as t,c as r,ah as i}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Helmut Horten – Rüstungsprofite und Zwangsarbeit (Johannisthal)","description":"Eine Untersuchung der Beteiligung Helmut Hortens an der Rüstungsindustrie im Dritten Reich und der Einsatz von Zwangsarbeitern in der Flugzeugwerk Johannisthal GmbH.","frontmatter":{"title":"Helmut Horten – Rüstungsprofite und Zwangsarbeit (Johannisthal)","description":"Eine Untersuchung der Beteiligung Helmut Hortens an der Rüstungsindustrie im Dritten Reich und der Einsatz von Zwangsarbeitern in der Flugzeugwerk Johannisthal GmbH."},"headers":[],"relativePath":"recherche/helmut-horten-ruestung-zwangsarbeit.md","filePath":"recherche/helmut-horten-ruestung-zwangsarbeit.md"}'),s={name:"recherche/helmut-horten-ruestung-zwangsarbeit.md"};function a(u,e,o,g,l,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="helmut-horten-rustungsprofite-und-zwangsarbeit" tabindex="-1">Helmut Horten: Rüstungsprofite und Zwangsarbeit <a class="header-anchor" href="#helmut-horten-rustungsprofite-und-zwangsarbeit" aria-label="Permalink to &quot;Helmut Horten: Rüstungsprofite und Zwangsarbeit&quot;">​</a></h1><p>Während die öffentliche Debatte um Helmut Horten lange Zeit auf die &quot;Arisierungen&quot; von Kaufhäusern (wie Alsberg) fokussiert war, brachte ein wissenschaftliches Gutachten (Hoeres, 2022) eine weitere, dunkle Facette seines Aufstiegs ans Licht: Die direkte Beteiligung an der Rüstungsproduktion und dem Einsatz von Zwangsarbeitern.</p><h2 id="die-flugzeugwerk-johannisthal-gmbh-fwj" tabindex="-1">Die Flugzeugwerk Johannisthal GmbH (FWJ) <a class="header-anchor" href="#die-flugzeugwerk-johannisthal-gmbh-fwj" aria-label="Permalink to &quot;Die Flugzeugwerk Johannisthal GmbH (FWJ)&quot;">​</a></h2><p>Ab <strong>Juni 1943</strong> wurde Helmut Horten Mitgesellschafter der <strong>Flugzeugwerk Johannisthal GmbH</strong> in Berlin. Gemeinsam mit seinem Geschäftspartner Wilhelm Reinold übernahm er Anteile an diesem Unternehmen, das als Zulieferer für die deutsche Luftwaffe fungierte.</p><h3 id="kernpunkte-der-beteiligung" tabindex="-1">Kernpunkte der Beteiligung: <a class="header-anchor" href="#kernpunkte-der-beteiligung" aria-label="Permalink to &quot;Kernpunkte der Beteiligung:&quot;">​</a></h3><ul><li><strong>Rüstungsproduktion:</strong> Das Werk reparierte und fertigte Teile für Kampfflugzeuge, unter anderem für die Typen <strong>Bf 109</strong>, <strong>Ju 87 (&quot;Stuka&quot;)</strong> und Flugzeuge der Firma <strong>Focke-Wulf</strong>.</li><li><strong>Expansion:</strong> Das Unternehmen wuchs während des Krieges massiv an. Horten investierte in einer Phase, in der der Bedarf an Rüstungsgütern seinen Höhepunkt erreichte.</li><li><strong>Wirtschaftlicher Vorteil:</strong> Trotz der Kriegswirren erwirtschaftete das Werk erhebliche Gewinne, von denen Horten als Gesellschafter profitierte.</li></ul><h2 id="systematische-zwangsarbeit" tabindex="-1">Systematische Zwangsarbeit <a class="header-anchor" href="#systematische-zwangsarbeit" aria-label="Permalink to &quot;Systematische Zwangsarbeit&quot;">​</a></h2><p>Der Betrieb der Flugzeugwerk Johannisthal GmbH war in den Jahren 1942 bis 1945 nur durch den massiven Einsatz von Zwangsarbeitern möglich. Das Gutachten von 2022 belegt, dass Horten Mitverantwortung für ein System trug, das Menschen unter unmenschlichen Bedingungen ausbeutete.</p><h3 id="fakten-zum-arbeitseinsatz" tabindex="-1">Fakten zum Arbeitseinsatz: <a class="header-anchor" href="#fakten-zum-arbeitseinsatz" aria-label="Permalink to &quot;Fakten zum Arbeitseinsatz:&quot;">​</a></h3><ul><li><strong>Zwangsarbeiter-Lager:</strong> In unmittelbarer Nähe des Werks existierten Barackenlager (z.B. das Lager &quot;Arbeitsgemeinschaft Rudow&quot;), in denen Hunderte von Menschen interniert waren.</li><li><strong>Zusammensetzung:</strong> Die Belegschaft bestand zu einem signifikanten Teil aus: <ul><li><strong>Kriegsgefangenen</strong> (insbesondere aus der Sowjetunion).</li><li><strong>Zivilarbeitern</strong> aus besetzten Gebieten (Polen, Ukraine, Weißrussland).</li><li>Sogenannten <strong>&quot;Ostarbeitern&quot;</strong>.</li></ul></li><li><strong>Bedingungen:</strong> Die Arbeiter litten unter Mangelernährung, unzureichender medizinischer Versorgung und ständiger Bewachung. Dokumente belegen Misshandlungen durch Aufseher im Werk.</li></ul><h2 id="historische-einordnung" tabindex="-1">Historische Einordnung <a class="header-anchor" href="#historische-einordnung" aria-label="Permalink to &quot;Historische Einordnung&quot;">​</a></h2><p>Die Beteiligung an der FWJ widerlegt das Bild von Horten als reinem &quot;Einzelhändler&quot;, der sich aus der direkten Kriegsmaschinerie herausgehalten habe.</p><ol><li><strong>Opportunismus:</strong> Horten nutzte die Chance, in die strategisch wichtige Rüstungsindustrie einzusteigen, als die &quot;Arisierung&quot; von Kaufhäusern weitgehend abgeschlossen war.</li><li><strong>Profiteur der Vernichtung:</strong> Während jüdische Familien wie die Alsbergs deportiert und ermordet wurden, baute Horten sein Vermögen nicht nur auf deren ehemaligen Geschäften auf, sondern profitierte auch direkt von der Kriegswirtschaft und der Versklavung von Menschen.</li></ol><p>Diese Erkenntnisse sind ein zentraler Baustein für das Motiv der <strong>Marktbereinigung</strong> in unserer Mockumentary: Horten füllte nicht nur &quot;wirtschaftliche Lücken&quot; im Einzelhandel, sondern auch in der Fabrikation von Vernichtungswaffen.</p><hr><p><em>Quellen: Gutachten über den Vermögens- und Geschäftsaufbau von Helmut Horten, Prof. Dr. Peter Hoeres, 2022.</em></p>',16)])])}const m=n(s,[["render",a]]);export{c as __pageData,m as default};
